#include "apex/kdtree.hpp"

#include <algorithm>
#include <cmath>

namespace apex {

KDTree::KDTree(const double* points, std::int64_t point_count)
    : point_count_(point_count > 0 ? point_count : 0) {
    if (point_count_ == 0) {
        return;
    }
