// Marge sur l'AABB d'un triangle. La narrow phase accepte un impact
// legerement HORS du triangle (tolerance barycentrique 1e-13) et legerement
// derriere l'origine (-1e-6) : une AABB serree pourrait ecarter au broad
// phase un candidat que la narrow phase aurait retenu. La marge garantit que
// le BVH reste un SUR-ENSEMBLE, condition de l'equivalence.
constexpr double kBoxMargin = 1e-6;

inline double dot(const Vec3& a, const Vec3& b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

// Test rayon/AABB par la methode des tranches (slabs). `inv_direction` porte
// +/-inf sur un axe de direction nulle : le produit `0 * inf` donnerait NaN,
// d'ou le traitement explicite de ce cas.
inline bool ray_hits_box(const AABB& box, const Vec3& origin, const Vec3& inv_direction) {
    double tmin = kForwardTol;  // meme borne que le filtre "forward" de la narrow phase
    double tmax = std::numeric_limits<double>::infinity();

    const double o[3] = {origin.x, origin.y, origin.z};
    const double inv[3] = {inv_direction.x, inv_direction.y, inv_direction.z};
    const double lo[3] = {box.lo.x, box.lo.y, box.lo.z};
    const double hi[3] = {box.hi.x, box.hi.y, box.hi.z};

    for (int a = 0; a < 3; ++a) {
        if (std::isinf(inv[a])) {
            // Rayon parallele a cet axe : il ne peut traverser que s'il est
            // deja dans la tranche.
            if (o[a] < lo[a] || o[a] > hi[a]) {
                return false;
            }
            continue;
        }
        double t0 = (lo[a] - o[a]) * inv[a];
        double t1 = (hi[a] - o[a]) * inv[a];
        if (t0 > t1) {
            std::swap(t0, t1);
        }
        tmin = t0 > tmin ? t0 : tmin;
        tmax = t1 < tmax ? t1 : tmax;
        if (tmax < tmin) {
            return false;
        }
    }
    return true;
}

