    AABB box;
    box.lo = Vec3{kInf, kInf, kInf};
    box.hi = Vec3{-kInf, -kInf, -kInf};
    for (std::int64_t i = 0; i < count; ++i) {
        for (int a = 0; a < 3; ++a) {
            const double v = points[3 * i + a];
            (&box.lo.x)[a] = std::min((&box.lo.x)[a], v);
            (&box.hi.x)[a] = std::max((&box.hi.x)[a], v);
        }
    }
    for (int a = 0; a < 3; ++a) {
        (&box.lo.x)[a] -= radius;
        (&box.hi.x)[a] += radius;
    }
    return box;
}

