            out[3 * t + 0] = dir[0];
            out[3 * t + 1] = dir[1];
            out[3 * t + 2] = dir[2];
        } else {
            out[3 * t + 0] = bx / norm;
            out[3 * t + 1] = by / norm;
            out[3 * t + 2] = bz / norm;
        }
    }
