1	#include "apex/bvh.hpp"
2	
3	#include <algorithm>
4	#include <cmath>
5	#include <limits>
6	#include <unordered_set>
7	
8	namespace apex {
9	namespace {
10	
11	// Feuille des que le noeud tient dans ce nombre de triangles. Un seuil > 1
12	// evite une descente profonde pour un gain nul : le test d'AABB coute alors
13	// plus cher que les quelques tests de triangle qu'il economise.
14	constexpr std::int64_t kLeafSize = 4;
15	
16	inline double dot(const Vec3& a, const Vec3& b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
17	
18	// Recouvrement d'AABB, bornes INCLUSES - c'est la semantique de
19	// `rtree.intersection`, que cette descente remplace.
20	inline bool boxes_overlap(const AABB& a, const AABB& b) {
21	    return a.lo.x <= b.hi.x && a.hi.x >= b.lo.x && a.lo.y <= b.hi.y && a.hi.y >= b.lo.y &&
22	           a.lo.z <= b.hi.z && a.hi.z >= b.lo.z;
23	}
24	
25	// Cle de dedoublonnage : (location quantifiee a 8 decimales, index du rayon),
26	// transcription de `grouping.unique_rows` sur la pile
27	// `column_stack((locations, index_ray))`.
28	struct HitKey {
29	    std::int64_t x, y, z, ray;
30	    bool operator==(const HitKey& o) const {
31	        return x == o.x && y == o.y && z == o.z && ray == o.ray;
32	    }
33	};
34	
35	struct HitKeyHash {
36	    std::size_t operator()(const HitKey& k) const noexcept {
37	        std::size_t h = static_cast<std::size_t>(k.x) * 0x9E3779B97F4A7C15ULL;
38	        h ^= static_cast<std::size_t>(k.y) + 0x9E3779B97F4A7C15ULL + (h << 6) + (h >> 2);
39	        h ^= static_cast<std::size_t>(k.z) + 0x9E3779B97F4A7C15ULL + (h << 6) + (h >> 2);
40	        h ^= static_cast<std::size_t>(k.ray) + 0x9E3779B97F4A7C15ULL + (h << 6) + (h >> 2);
41	        return h;
42	    }
43	};
44	
45	// `trimesh.grouping.float_to_int` : multiplication par 10^digits puis
46	// troncature vers zero (`astype(np.int64)`), jamais un arrondi.
47	inline std::int64_t quantize(double value) {
48	    return static_cast<std::int64_t>(value * kMergeDigits);
49	}
50	
51	}  // namespace
52	
53	TriangleBVH::TriangleBVH(const double* triangles, const double* normals,
54	                         std::int64_t triangle_count)
55	    : triangle_count_(triangle_count > 0 ? triangle_count : 0) {
56	    if (triangle_count_ == 0) {
57	        return;
58	    }
59	    triangles_.assign(triangles, triangles + static_cast<std::size_t>(triangle_count_) * 9);
60	    normals_.assign(normals, normals + static_cast<std::size_t>(triangle_count_) * 3);
61	
62	    boxes_.resize(static_cast<std::size_t>(triangle_count_));
63	    centroids_.resize(static_cast<std::size_t>(triangle_count_));
64	    order_.resize(static_cast<std::size_t>(triangle_count_));
65	
66	    // AABB EXACTES, sans marge : ce sont celles que `triangles.bounds_tree`
67	    // indexe cote trimesh, et le jeu de candidats doit etre le meme.
68	    mesh_bounds_.lo = Vec3{std::numeric_limits<double>::infinity(),
69	                           std::numeric_limits<double>::infinity(),
70	                           std::numeric_limits<double>::infinity()};
71	    mesh_bounds_.hi = Vec3{-std::numeric_limits<double>::infinity(),
72	                           -std::numeric_limits<double>::infinity(),
73	                           -std::numeric_limits<double>::infinity()};
74	
75	    for (std::int64_t t = 0; t < triangle_count_; ++t) {
76	        const double* v = triangles_.data() + static_cast<std::size_t>(t) * 9;
77	        AABB& box = boxes_[static_cast<std::size_t>(t)];
78	        for (int a = 0; a < 3; ++a) {
79	            const double c0 = v[a];
80	            const double c1 = v[3 + a];
81	            const double c2 = v[6 + a];
82	            const double lo = std::min(c0, std::min(c1, c2));
83	            const double hi = std::max(c0, std::max(c1, c2));
84	            (&box.lo.x)[a] = lo;
85	            (&box.hi.x)[a] = hi;
86	            (&centroids_[static_cast<std::size_t>(t)].x)[a] = (c0 + c1 + c2) / 3.0;
87	            (&mesh_bounds_.lo.x)[a] = std::min((&mesh_bounds_.lo.x)[a], lo);
88	            (&mesh_bounds_.hi.x)[a] = std::max((&mesh_bounds_.hi.x)[a], hi);
89	        }
90	        order_[static_cast<std::size_t>(t)] = static_cast<std::int32_t>(t);
91	    }
92	
93	    nodes_.reserve(static_cast<std::size_t>(triangle_count_) * 2);
94	    root_ = build(0, triangle_count_);
95	}
