97	std::int32_t TriangleBVH::build(std::int64_t lo, std::int64_t hi) {
98	    if (lo >= hi) {
99	        return -1;
100	    }
101	
102	    const auto node_index = static_cast<std::int32_t>(nodes_.size());
103	    nodes_.push_back(Node{});
104	
105	    AABB box;
106	    box.lo = Vec3{std::numeric_limits<double>::infinity(), std::numeric_limits<double>::infinity(),
107	                  std::numeric_limits<double>::infinity()};
108	    box.hi = Vec3{-std::numeric_limits<double>::infinity(),
109	                  -std::numeric_limits<double>::infinity(),
110	                  -std::numeric_limits<double>::infinity()};
111	    Vec3 centroid_lo = box.lo;
112	    Vec3 centroid_hi = box.hi;
113	
114	    for (std::int64_t i = lo; i < hi; ++i) {
115	        const AABB& tb = boxes_[static_cast<std::size_t>(order_[static_cast<std::size_t>(i)])];
116	        const Vec3& c = centroids_[static_cast<std::size_t>(order_[static_cast<std::size_t>(i)])];
117	        for (int a = 0; a < 3; ++a) {
118	            (&box.lo.x)[a] = std::min((&box.lo.x)[a], (&tb.lo.x)[a]);
119	            (&box.hi.x)[a] = std::max((&box.hi.x)[a], (&tb.hi.x)[a]);
120	            (&centroid_lo.x)[a] = std::min((&centroid_lo.x)[a], (&c.x)[a]);
121	            (&centroid_hi.x)[a] = std::max((&centroid_hi.x)[a], (&c.x)[a]);
122	        }
123	    }
124	    nodes_[static_cast<std::size_t>(node_index)].box = box;
125	
126	    const std::int64_t span = hi - lo;
127	    if (span <= kLeafSize) {
128	        Node& leaf = nodes_[static_cast<std::size_t>(node_index)];
129	        leaf.first = static_cast<std::int32_t>(lo);
130	        leaf.count = static_cast<std::int32_t>(span);
131	        return node_index;
132	    }
133	
134	    // Axe le plus etendu au sens des CENTROIDES (et non des AABB) : c'est ce
135	    // qui separe reellement les triangles, une AABB large pouvant deborder
136	    // des deux cotes du plan de coupe.
137	    int axis = 0;
138	    double extent = centroid_hi.x - centroid_lo.x;
139	    if (centroid_hi.y - centroid_lo.y > extent) {
140	        extent = centroid_hi.y - centroid_lo.y;
141	        axis = 1;
142	    }
143	    if (centroid_hi.z - centroid_lo.z > extent) {
144	        axis = 2;
145	    }
146	
147	    const std::int64_t mid = lo + span / 2;
148	    std::nth_element(order_.begin() + lo, order_.begin() + mid, order_.begin() + hi,
149	                     [this, axis](std::int32_t a, std::int32_t b) {
150	                         const double ca = (&centroids_[static_cast<std::size_t>(a)].x)[axis];
151	                         const double cb = (&centroids_[static_cast<std::size_t>(b)].x)[axis];
152	                         if (ca != cb) {
153	                             return ca < cb;
154	                         }
155	                         return a < b;  // ordre total : construction deterministe
156	                     });
157	
158	    const std::int32_t left = build(lo, mid);
159	    const std::int32_t right = build(mid, hi);
160	    Node& n = nodes_[static_cast<std::size_t>(node_index)];
161	    n.left = left;
162	    n.right = right;
163	    n.count = 0;
164	    return node_index;
165	}
