167	void TriangleBVH::gather(std::int32_t node_index, const AABB& query,
168	                         std::vector<std::int32_t>& out) const {
169	    if (node_index < 0) {
170	        return;
171	    }
172	    const Node& n = nodes_[static_cast<std::size_t>(node_index)];
173	    if (!boxes_overlap(n.box, query)) {
174	        return;
175	    }
176	    if (n.count > 0) {
177	        // Feuille : le test par noeud est conservateur, chaque triangle est
178	        // re-teste individuellement pour ne pas elargir le jeu de candidats.
179	        for (std::int32_t i = 0; i < n.count; ++i) {
180	            const std::int32_t t = order_[static_cast<std::size_t>(n.first + i)];
181	            if (boxes_overlap(boxes_[static_cast<std::size_t>(t)], query)) {
182	                out.push_back(t);
183	            }
184	        }
185	        return;
186	    }
187	    gather(n.left, query, out);
188	    gather(n.right, query, out);
