191	AABB TriangleBVH::ray_bounds(const Vec3& origin, const Vec3& direction) const {
192	    // Transcription de `ray_triangle.ray_bounds`, un rayon a la fois.
193	    const double d[3] = {direction.x, direction.y, direction.z};
194	    const double o[3] = {origin.x, origin.y, origin.z};
195	
196	    // Axe dominant du rayon (`np.abs(ray_directions).argmax`) - `argmax` rend
197	    // le PREMIER maximum en cas d'egalite, d'où les comparaisons strictes.
198	    int axis = 0;
199	    double best = std::abs(d[0]);
200	    if (std::abs(d[1]) > best) {
201	        best = std::abs(d[1]);
202	        axis = 1;
203	    }
204	    if (std::abs(d[2]) > best) {
205	        axis = 2;
206	    }
207	
208	    const double axis_dir = d[axis];
209	    const double axis_ori = o[axis];
210	    const double axis_bound[2] = {(&mesh_bounds_.lo.x)[axis], (&mesh_bounds_.hi.x)[axis]};
211	
212	    // `t = zeros; t[nonzero] = (bound - ori)/dir` puis `t[t < buffer] = buffer`.
213	    // Une direction nulle sur l'axe dominant (donc un vecteur nul) laisse les
214	    // deux t a zero, ensuite releves a buffer_dist - comportement conserve.
215	    double t[2] = {0.0, 0.0};
216	    if (axis_dir != 0.0) {
217	        t[0] = (axis_bound[0] - axis_ori) / axis_dir;
218	        t[1] = (axis_bound[1] - axis_ori) / axis_dir;
219	    }
220	    for (int i = 0; i < 2; ++i) {
221	        if (t[i] < kRayBufferDist) {
222	            t[i] = kRayBufferDist;
223	        }
224	    }
225	
226	    AABB box;
227	    for (int a = 0; a < 3; ++a) {
228	        const double on_a = d[a] * t[0] + o[a];
229	        const double on_b = d[a] * t[1] + o[a];
230	        (&box.lo.x)[a] = std::min(on_a, on_b) - kRayBufferDist;
231	        (&box.hi.x)[a] = std::max(on_a, on_b) + kRayBufferDist;
232	    }
233	    return box;
234	}
