236	std::vector<RayHit> TriangleBVH::intersects_location(const double* origins,
237	                                                     const double* directions,
238	                                                     std::int64_t ray_count) const {
239	    std::vector<RayHit> hits;
240	    if (triangle_count_ == 0 || ray_count <= 0) {
241	        return hits;
242	    }
243	
244	    std::vector<std::int32_t> candidates;
245	    std::unordered_set<HitKey, HitKeyHash> seen;
246	
247	    for (std::int64_t r = 0; r < ray_count; ++r) {
248	        const Vec3 origin{origins[3 * r], origins[3 * r + 1], origins[3 * r + 2]};
249	        const Vec3 direction{directions[3 * r], directions[3 * r + 1], directions[3 * r + 2]};
250	
251	        candidates.clear();
252	        gather(root_, ray_bounds(origin, direction), candidates);
253	        if (candidates.empty()) {
254	            continue;
255	        }
256	        seen.clear();
257	
258	        for (const std::int32_t t : candidates) {
259	            const double* v = triangles_.data() + static_cast<std::size_t>(t) * 9;
260	            const double* nrm = normals_.data() + static_cast<std::size_t>(t) * 3;
261	
262	            // --- 1. intersections.planes_lines -------------------------------
263	            // plane_origin = premier sommet du triangle, comme trimesh.
264	            const Vec3 plane_origin{v[0], v[1], v[2]};
265	            const Vec3 plane_normal{nrm[0], nrm[1], nrm[2]};
266	            const Vec3 origin_vector{plane_origin.x - origin.x, plane_origin.y - origin.y,
267	                                     plane_origin.z - origin.z};
268	
269	            const double projection_ori = dot(origin_vector, plane_normal);
270	            const double projection_dir = dot(direction, plane_normal);
271	            if (!(std::abs(projection_dir) > kPlaneParallelEps)) {
272	                continue;
273	            }
274	            const double distance = projection_ori / projection_dir;
275	            // `on_plane = line_direction * distance + line_origin` - meme
276	            // ordre (multiplication puis addition) que le numpy de trimesh.
277	            const Vec3 location{direction.x * distance + origin.x,
278	                                direction.y * distance + origin.y,
279	                                direction.z * distance + origin.z};
280	
281	            // --- 2. triangles.points_to_barycentric, methode "cramer" --------
282	            const Vec3 edge0{v[3] - v[0], v[4] - v[1], v[5] - v[2]};
283	            const Vec3 edge1{v[6] - v[0], v[7] - v[1], v[8] - v[2]};
284	            const Vec3 w{location.x - v[0], location.y - v[1], location.z - v[2]};
285	
286	            const double dot00 = dot(edge0, edge0);
287	            const double dot01 = dot(edge0, edge1);
288	            const double dot02 = dot(edge0, w);
289	            const double dot11 = dot(edge1, edge1);
290	            const double dot12 = dot(edge1, w);
291	
292	            const double inverse_denominator = 1.0 / (dot00 * dot11 - dot01 * dot01);
293	            const double b2 = (dot00 * dot12 - dot01 * dot02) * inverse_denominator;
294	            const double b1 = (dot11 * dot02 - dot01 * dot12) * inverse_denominator;
295	            const double b0 = 1.0 - b1 - b2;
296	
297	            // --- 3. appartenance au triangle ---------------------------------
298	            const bool inside = b0 > -kBarycentricTol && b1 > -kBarycentricTol &&
299	                                b2 > -kBarycentricTol && b0 < 1.0 + kBarycentricTol &&
300	                                b1 < 1.0 + kBarycentricTol && b2 < 1.0 + kBarycentricTol;
301	            if (!inside) {
302	                continue;
303	            }
304	
305	            // --- 4. filtre "vers l'avant" ------------------------------------
306	            // Produit scalaire avec la direction telle quelle (non
307	            // normalisee), comme `util.diagonal_dot` cote trimesh.
308	            const Vec3 to_hit{location.x - origin.x, location.y - origin.y,
309	                              location.z - origin.z};
310	            if (!(dot(to_hit, direction) > kForwardTol)) {
311	                continue;
312	            }
313	
314	            // --- 5. dedoublonnage (location, index_ray) ----------------------
315	            const HitKey key{quantize(location.x), quantize(location.y), quantize(location.z), r};
316	            if (!seen.insert(key).second) {
317	                continue;
318	            }
319	
320	            hits.push_back(RayHit{r, t, location});
321	        }
322	    }
323	    return hits;
324	}
