#include "apex/mesh_repair.hpp"

#include <algorithm>
#include <cmath>
#include <limits>

namespace apex {
namespace {

// Tolerance de separation - transcription exacte de `_COPLANAR_EPS`.
constexpr double kCoplanarEps = 1e-9;
// Norme d'axe en dessous de laquelle il est ignore (aretes paralleles ou
// face degeneree) - transcription de `norm < 1e-12`.
constexpr double kAxisNormEps = 1e-12;

// Feuille des que le noeud tient dans ce nombre de triangles - meme seuil
// que TriangleBVH (bvh.cpp), meme raisonnement (le test d'AABB couterait
// plus cher que les quelques tests de triangle qu'il economise).
constexpr std::int64_t kLeafSize = 4;

inline Vec3 sub(const Vec3& a, const Vec3& b) { return Vec3{a.x - b.x, a.y - b.y, a.z - b.z}; }
inline Vec3 cross(const Vec3& a, const Vec3& b) {
    return Vec3{a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x};
}
inline double dot(const Vec3& a, const Vec3& b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
inline double norm(const Vec3& a) { return std::sqrt(dot(a, a)); }

inline bool boxes_overlap(const AABB& a, const AABB& b) {
    return a.lo.x <= b.hi.x && a.hi.x >= b.lo.x && a.lo.y <= b.hi.y && a.hi.y >= b.lo.y &&
           a.lo.z <= b.hi.z && a.hi.z >= b.lo.z;

